g.metadata:
{
  "schema": "ppt-master.semantic-table.v2",
  "name": "exposure-matrix",
  "x": 64, "y": 236, "width": 1152, "height": 216,
  "strict_grid": true,
  "column_widths": [276, 438, 438],
  "row_heights": [48, 84, 84],
  "style": {
    "font_family": "Calibri",
    "font_size": 20,
    "header_fill": "#003657",
    "header_text": "#FBF8F2",
    "body_text": "#1E1E1E",
    "band_row": false,
    "valign": "middle"
  },
  "defaults": {
    "cell": {
      "padding": {"left": 16, "right": 16, "top": 6, "bottom": 6},
      "borders": {
        "left": {"style": "none"}, "right": {"style": "none"},
        "top": {"style": "solid", "color": "#D6CFC2", "width": 1},
        "bottom": {"style": "solid", "color": "#D6CFC2", "width": 1}
      }
    }
  },
  "columns": [
    {"text": "Exposure", "bold": true, "align": "l"},
    {"text": "Carry", "bold": true, "align": "l"},
    {"text": "GP invested capital", "bold": true, "align": "l"}
  ],
  "rows": [
    [
      {"text": "Qualifying investment profits", "bold": true, "color": "#003657"},
      {"text": "Potential performance compensation", "fill": "#DDE4F4"},
      {"text": "Investment return under agreed terms", "color": "#003657"}
    ],
    [
      {"text": "Investment losses", "bold": true, "color": "#003657"},
      {"text": "Performance compensation may be absent", "fill": "#DDE4F4"},
      {"text": "Contributed capital may be lost", "color": "#A33D3D", "bold": true}
    ]
  ]
}
